"""Generates the field declarations of JS store models from the Python models.

A generated file has to be named ``*.generated.js``. It lives in the
``static/src`` of an addon, and starts with a header of line comments::

    // @generated by `odoo-bin js_fields` -- do not edit below the options
    //
    // model: mail.message
    // addons: mail
    // fields: author_id, body, child_ids, parent_id

The header is written by hand, the rest of the file is (re)written by the
tool: it exports one object of field declarations, to use as the ``fields`` of
a model class.

Options:

``model`` (required)
    Name of the Python model.

``addons``
    Only the fields introduced by these addons. By default, the fields of the
    addon of the file and of all its dependencies: the ones that exist for
    sure when the file is loaded. An addon listed here has to be the addon of
    the file or one of its dependencies.

``fields``
    Only these fields. Each of them has to exist and to be supported.

``exclude``
    All fields but these. Each of them has to exist. Cannot be combined with
    ``fields``.

``export``
    Name of the exported object, ``mailMessageFields`` by default for the
    model ``mail.message``.

A value can continue on the following comment lines.

Without ``fields``, the following are left out: ``id`` (records always have
one), the log access fields, custom fields, the fields whose type has no JS
declaration, and the relational fields to a model without JS class.

Relational fields are typed with the JS class of their comodel. The classes
are found in the ``static/src`` of the addons: a class with a
``static _name`` that extends ``Model``, imported from
``@web/next/store/model``, declares a model, and a class with a
``static _inherit`` extends one. When a model has several classes, the most
extended ones among the dependencies of the addon of the file are used.
"""
from __future__ import annotations

import functools
import posixpath
import re
from dataclasses import dataclass
from pathlib import Path

from odoo.modules.module import Manifest
from odoo.orm.models import LOG_ACCESS_COLUMNS

MARKER = "// @generated by `odoo-bin js_fields`"
SUFFIX = ".generated.js"
FIELDS_MODULE = "@web/next/store/fields"
MODEL_MODULE = "@web/next/store/model"
LINE_WIDTH = 100
INDENT = "    "

# field type -> factory of `fields`, in FIELDS_MODULE
FACTORIES = {
    'char': 'Char',
    'text': 'Text',
    'html': 'Html',
    'integer': 'Integer',
    'float': 'Float',
    'monetary': 'Monetary',
    'boolean': 'Boolean',
    'date': 'Date',
    'datetime': 'Datetime',
    'selection': 'Selection',
    'json': 'Json',
    'many2one': 'Many2one',
    'one2many': 'One2many',
    'many2many': 'Many2many',
}
RELATIONAL_TYPES = ('many2one', 'one2many', 'many2many')

LIST_OPTIONS = ('addons', 'fields', 'exclude')
OPTIONS = ('model', 'export', *LIST_OPTIONS)

OPTION_RE = re.compile(r"^//\s*(\w+):\s*(.*)$")
IDENTIFIER_RE = re.compile(r"^[A-Za-z_$][\w$]*$")
COMMENT_RE = re.compile(r"/\*.*?\*/|//[^\n]*", re.DOTALL)
IMPORT_RE = re.compile(r"""\bimport\s*\{([^}]*)\}\s*from\s*["']([^"']+)["']""")
CLASS_RE = re.compile(r"^[ \t]*(export\s+)?class\s+(\w+)\s+extends\s+([^{]+)\{", re.MULTILINE)
STATIC_RE = re.compile(r"""\bstatic\s+(_name|_inherit)\s*=\s*["']([\w.]+)["']""")


class JsFieldsError(Exception):
    """A generated file that cannot be (re)generated."""


@dataclass(frozen=True)
class Addon:
    name: str
    path: Path
    depends: tuple[str, ...] = ()


@dataclass(frozen=True)
class JsClass:
    """A JS class of a model: its declaration, or an extension."""
    name: str
    model: str
    addon: str
    module: str  # what to import it from, e.g. "@mail/core/common/partner_model"
    extension: bool


@dataclass(frozen=True)
class Directive:
    """The header of a generated file."""
    header: str
    model: str
    addons: tuple[str, ...] | None = None
    fields: tuple[str, ...] | None = None
    exclude: tuple[str, ...] | None = None
    export: str | None = None

    @property
    def export_name(self) -> str:
        if self.export:
            return self.export
        first, *others = re.split(r"[._]+", self.model)
        return first + "".join(part.capitalize() for part in others) + "Fields"


@dataclass(frozen=True)
class Result:
    path: Path
    status: str  # 'unchanged', 'updated', 'outdated' (check only) or 'error'
    messages: tuple[str, ...] = ()


# ------------------------------------------------------------------------------
# Header
# ------------------------------------------------------------------------------

def parse_directive(content: str) -> Directive:
    lines = content.splitlines()
    if not lines or not lines[0].startswith(MARKER):
        raise JsFieldsError(f"the first line has to start with: {MARKER}")
    header = [lines[0]]
    options: dict[str, list[str]] = {}
    current = None
    for line in lines[1:]:
        if not line.startswith("//"):
            break
        header.append(line)
        text = line[2:].strip()
        if not text:
            current = None
        elif match := OPTION_RE.match(line):
            current = match[1]
            if current not in OPTIONS:
                raise JsFieldsError(
                    f"unknown option {current!r}, expected one of: {', '.join(OPTIONS)}")
            if current in options:
                raise JsFieldsError(f"option {current!r} is given twice")
            options[current] = [match[2]]
        elif current:
            options[current].append(text)

    values = {
        name: tuple(value for value in re.split(r"[\s,]+", " ".join(parts)) if value)
        for name, parts in options.items()
    }
    for name in ('model', 'export'):
        if name in values and len(values[name]) != 1:
            raise JsFieldsError(f"option {name!r} takes exactly one value")
    if 'model' not in values:
        raise JsFieldsError("option 'model' is required")
    if 'fields' in values and 'exclude' in values:
        raise JsFieldsError("options 'fields' and 'exclude' cannot be combined")
    export = values['export'][0] if 'export' in values else None
    if export and not IDENTIFIER_RE.match(export):
        raise JsFieldsError(f"option 'export' is not a valid name: {export!r}")
    return Directive(
        header="\n".join(header),
        model=values['model'][0],
        export=export,
        **{name: values[name] for name in LIST_OPTIONS if name in values},
    )


# ------------------------------------------------------------------------------
# JS classes
# ------------------------------------------------------------------------------

def get_js_module(addon: Addon, path: Path) -> str:
    """ The name a JS file is imported with: ``@addon/path/in/static/src``. """
    relative = path.relative_to(addon.path / "static" / "src").with_suffix("")
    return f"@{addon.name}/{relative.as_posix()}"


def scan_js_classes(addon: Addon, path: Path, content: str) -> tuple[list[JsClass], list[str]]:
    """ Find the classes of store models in the content of a JS file.

    :return: the classes, and warnings about the ones that cannot be used
    """
    content = COMMENT_RE.sub("", content)
    module = get_js_module(addon, path)

    # local names of `Model`
    model_names = set()
    for names, specifier in IMPORT_RE.findall(content):
        imported_module = specifier.removesuffix(".js")
        if specifier.startswith("."):
            imported_module = posixpath.normpath(
                posixpath.join(posixpath.dirname(module), imported_module))
        if imported_module != MODEL_MODULE:
            continue
        for name in names.split(","):
            imported, _, local = name.strip().partition(" as ")
            if imported.strip() == "Model":
                model_names.add((local or imported).strip())

    classes = []
    warnings = []
    declarations = list(CLASS_RE.finditer(content))
    seen = set()
    for static in STATIC_RE.finditer(content):
        declaration = next(
            (match for match in reversed(declarations) if match.end() <= static.start()), None)
        if not declaration:
            continue
        exported, name, base = declaration.groups()
        kind, model = static.groups()
        base = re.sub(r"[()\s]", "", base)
        if kind == '_name' and base not in model_names:
            # not a store model, e.g. a record of the mail store
            continue
        if (name, kind) in seen:
            continue
        seen.add((name, kind))
        if not exported:
            warnings.append(
                f"{path}: class {name} of model {model!r} is ignored, as it is not exported")
            continue
        classes.append(JsClass(name, model, addon.name, module, extension=kind == '_inherit'))
    # a class with both statics is an extension
    extensions = {cls.name for cls in classes if cls.extension}
    classes = [cls for cls in classes if cls.extension or cls.name not in extensions]
    return classes, warnings


def find_js_classes(addons: dict[str, Addon]) -> tuple[dict[str, list[JsClass]], list[str]]:
    """ Find the classes of store models in the given addons, by model name. """
    classes: dict[str, list[JsClass]] = {}
    warnings = []
    for addon in addons.values():
        src = addon.path / "static" / "src"
        if not src.is_dir():
            continue
        for path in sorted(src.rglob("*.js")):
            try:
                content = path.read_text(encoding="utf-8")
            except (OSError, UnicodeDecodeError):
                continue
            if "_name" not in content and "_inherit" not in content:
                continue
            found, found_warnings = scan_js_classes(addon, path, content)
            warnings += found_warnings
            for cls in found:
                classes.setdefault(cls.model, []).append(cls)
    return classes, warnings


# ------------------------------------------------------------------------------
# Generation
# ------------------------------------------------------------------------------

def get_addons() -> dict[str, Addon]:
    """ The addons of the addons path, by name. """
    return {
        manifest.name: Addon(manifest.name, Path(manifest.path).resolve(), tuple(manifest['depends']))
        for manifest in Manifest.all_addon_manifests()
    }


class FieldsGenerator:
    """ Generates the content of generated files.

    :param env: an environment on the database to read the models from
    :param addons: the addons to look for JS classes in, by name
    """

    def __init__(self, env, addons: dict[str, Addon]):
        self.env = env
        self.addons = addons
        self.classes, self.warnings = find_js_classes(addons)
        self.installed = set(
            env['ir.module.module'].search([('state', '=', 'installed')]).mapped('name'))
        self.closure = functools.cache(self._closure)
        self.field_addons = functools.cache(self._field_addons)

    def _closure(self, addon_name: str) -> frozenset[str]:
        """ The addon, and its direct and indirect dependencies. """
        result = {addon_name, 'base'}
        if addon := self.addons.get(addon_name):
            for dependency in addon.depends:
                result |= self.closure(dependency)
        return frozenset(result)

    def _field_addons(self, field) -> frozenset[str]:
        """ The addons needed for a field to exist: the one that introduces it. For a field
        inherited from a parent model (`_inherits`), the ones that introduce the field on the
        parent model and the many2one to it.
        """
        if field.inherited:
            delegate = self.env[field.model_name]._fields[field.related.split('.')[0]]
            return self.field_addons(delegate) | self.field_addons(field.inherited_field)
        return frozenset({field._modules[0] if field._modules else 'base'})

    def get_addon(self, path: Path) -> Addon:
        for parent in path.parents:
            addon = self.addons.get(parent.name)
            if addon and addon.path == parent:
                return addon
        raise JsFieldsError("not in an addon of the addons path")

    def get_classes(self, model_name: str, addon_name: str) -> list[JsClass]:
        """ The most extended JS classes of a model, among the ones the given addon can rely
        on. More than one when independent addons extend the model.
        """
        closure = self.closure(addon_name)
        visible = [cls for cls in self.classes.get(model_name, ()) if cls.addon in closure]

        def is_extended_by(cls, other):
            if cls.addon == other.addon:
                return other.extension and not cls.extension
            return cls.addon in self.closure(other.addon)

        return sorted(
            (cls for cls in visible if not any(is_extended_by(cls, other) for other in visible)),
            key=lambda cls: cls.name,
        )

    def generate(self, path: Path) -> tuple[str, list[str]]:
        """ Compute the content of a generated file from its header.

        :return: the content, and notes about the fields that were left out
        """
        if not path.name.endswith(SUFFIX):
            raise JsFieldsError(f"a generated file has to be named *{SUFFIX}")
        directive = parse_directive(path.read_text(encoding="utf-8"))
        addon = self.get_addon(path)
        closure = self.closure(addon.name)
        if addon.name not in self.installed:
            raise JsFieldsError(f"addon {addon.name!r} is not installed in the database")
        if directive.model not in self.env:
            raise JsFieldsError(f"unknown model {directive.model!r}")
        model = self.env[directive.model]

        allowed = closure
        for name in directive.addons or ():
            if name not in closure:
                raise JsFieldsError(
                    f"addon {name!r} is not {addon.name!r} or one of its dependencies")
        if directive.addons is not None:
            allowed = frozenset().union(*(self.closure(name) for name in directive.addons))

        def is_selected(field):
            needed = self.field_addons(field)
            if directive.addons is not None and needed.isdisjoint(directive.addons):
                return False
            return needed <= allowed

        def why_unsupported(field):
            if field.type not in FACTORIES:
                return f"type {field.type!r} has no JS declaration"
            if field.type in RELATIONAL_TYPES and not self.get_classes(field.comodel_name, addon.name):
                return f"model {field.comodel_name!r} has no JS class {addon.name!r} can rely on"
            return None

        # a listed field has to be one that can be generated here: the header is then valid or
        # not whatever the other addons installed in the database
        for name in (*(directive.fields or ()), *(directive.exclude or ())):
            if name not in model._fields:
                raise JsFieldsError(f"unknown field {name!r} on model {directive.model!r}")
            if not is_selected(model._fields[name]):
                origin = ", ".join(sorted(self.field_addons(model._fields[name])))
                expected = ", ".join(sorted(directive.addons or closure))
                raise JsFieldsError(
                    f"field {name!r} comes from addon(s) {origin}, not from: {expected}")

        selected = []
        notes = []
        if directive.fields is not None:
            for name in sorted(set(directive.fields)):
                field = model._fields[name]
                if name == 'id':
                    raise JsFieldsError("field 'id' cannot be listed: records always have an id")
                if reason := why_unsupported(field):
                    raise JsFieldsError(f"field {name!r} cannot be generated: {reason}")
                selected.append(field)
        else:
            skipped = {'id', *LOG_ACCESS_COLUMNS, *(directive.exclude or ())}
            for name, field in sorted(model._fields.items()):
                if name in skipped or field.manual or not is_selected(field):
                    continue
                if reason := why_unsupported(field):
                    notes.append(f"field {name!r} is left out: {reason}")
                    continue
                selected.append(field)

        return self._render(directive, addon, selected), notes

    def _render(self, directive: Directive, addon: Addon, fields: list) -> str:
        entries = []
        kinds = set()
        imports: dict[str, str] = {}  # class name -> module
        for field in fields:
            factory = FACTORIES[field.type]
            if field.type not in RELATIONAL_TYPES:
                entries.append(f"{INDENT}{field.name}: fields.{factory}(),")
                continue
            classes = self.get_classes(field.comodel_name, addon.name)
            for cls in classes:
                if imports.setdefault(cls.name, cls.module) != cls.module:
                    raise JsFieldsError(
                        f"two classes are named {cls.name!r}: in {cls.module} and {imports[cls.name]}")
            kinds.add(factory)
            comodel_type = " & ".join(cls.name for cls in classes)
            cast = f"/** @type {{{factory}<{comodel_type}>}} */"
            call = f'fields.{factory}("{field.comodel_name}")'
            inverse = field.type == 'one2many' and field.inverse_name
            # the inverse of a one2many can be a many2one_reference, which is not a relation in JS
            if inverse and self.env[field.comodel_name]._fields[inverse].type == 'many2one':
                call = f'fields.{factory}("{field.comodel_name}", {{ inverse: "{inverse}" }})'
            entry = f"{INDENT}{field.name}: {cast} ({call}),"
            if len(entry) > LINE_WIDTH:
                entry = f"{INDENT}{field.name}: {cast} (\n{INDENT * 2}{call}\n{INDENT}),"
            entries.append(entry)

        lines = [directive.header, "", f'import {{ fields }} from "{FIELDS_MODULE}";']
        if kinds:
            lines.append(f'/** @import {{ {", ".join(sorted(kinds))} }} from "{FIELDS_MODULE}" */')
        names_by_module: dict[str, list[str]] = {}
        for name, module in imports.items():
            names_by_module.setdefault(module, []).append(name)
        lines.extend(
            f'/** @import {{ {", ".join(sorted(names))} }} from "{module}" */'
            for module, names in sorted(names_by_module.items())
        )
        lines.append("")
        if entries:
            lines += [f"export const {directive.export_name} = {{", *entries, "};"]
        else:
            lines.append(f"export const {directive.export_name} = {{}};")
        return "\n".join(lines) + "\n"


def find_generated_files(roots: list[Path]) -> list[Path]:
    """ The generated files in the given files and directories. """
    paths = set()
    for root in roots:
        candidates = [root] if root.is_file() else root.rglob(f"*{SUFFIX}")
        for path in candidates:
            if path == root:
                paths.add(path)
                continue
            try:
                with path.open(encoding="utf-8") as file:
                    if file.readline().startswith(MARKER):
                        paths.add(path)
            except (OSError, UnicodeDecodeError):
                continue
    return sorted(paths)


def run(generator: FieldsGenerator, roots: list[Path] | None = None, check: bool = False) -> list[Result]:
    """ (Re)generate the generated files found in ``roots``, by default in all addons.

    :param check: do not write anything, only report the files that are not up to date
    """
    if roots is None:
        roots = [addon.path / "static" / "src" for addon in generator.addons.values()]
        roots = [root for root in roots if root.is_dir()]
    results = []
    for path in find_generated_files([root.resolve() for root in roots]):
        try:
            content, notes = generator.generate(path)
        except JsFieldsError as error:
            results.append(Result(path, 'error', (str(error),)))
            continue
        if content == path.read_text(encoding="utf-8"):
            status = 'unchanged'
        elif check:
            status = 'outdated'
        else:
            path.write_text(content, encoding="utf-8")
            status = 'updated'
        results.append(Result(path, status, tuple(notes)))
    return results
